\textbf{Tools:} \small{Image data pipelines, Annotation workflows, Image Annotation Workflows} \\
\textbf{Other:} \small{Manufacturing quality control, Inspection systems, Manufacturing Quality Inspection, Quality Inspection Systems} \\
\end{itemize}
\section{Experience}
{\small
\resumeSubHeadingListStart

\resumeSubheading
  {Machine Learning Intern}{May 2025 -- August 2025}
  {Ayar Labs}{Santa Clara, CA}
  \resumeItemListStart
    \resumeItem{Developed computer vision defect-detection models for manufacturing/quality inspection imagery using PyTorch and OpenCV inspection systems, improving defect detection F1 by 7 points on a held-out inspection set.}
    \resumeItem{Designed image data pipelines to feed training and evaluation for defect detection, using OpenCV and PyTorch to streamline preprocessing across inspection batches.}
    \resumeItem{Orchestrated annotation workflows with image data pipelines to enable inspection systems readiness, then supported deploying models in edge or real-time environments, reducing time-to-deploy new labeled defect classes from 2 weeks to 4 days.}
  \resumeItemListEnd

\resumeSubheading
  {Machine Learning Intern}{July 2024 -- December 2024}
  {Indian Institute of Technology, Indore}{Indore, India}
  \resumeItemListStart
    \resumeItem{Created and supported annotation workflows for manufacturing defect labels, applying manufacturing quality control standards to generate training-ready datasets with OpenCV, orchestrating 44 DAG tasks across 4 worker nodes.}
    \resumeItem{Productionized real-time or edge inference systems for inspection use cases by integrating TensorFlow and PyTorch defect-detection models into a real-time environment scoring service, meeting 30 FPS inference throughput on 640x480 inspection frames.}
    \resumeItem{Enhanced latency/throughput constraints in inspection environments by optimizing OpenCV preprocessing and computer vision models running on PyTorch, reducing end-to-end latency from 120 ms to 55 ms per image while keeping in.}
  \resumeItemListEnd

\resumeSubheading
  {Machine Learning Intern}{January 2024 -- June 2024}
  {National Institute of Technology, Jaipur}{Jaipur, India}
  \resumeItemListStart
    \resumeItem{Prototyped OpenCV-based preprocessing for inspection images to support computer vision defect detection workflows, reducing pipeline failure rate from 18\% to under 12\%.}
    \resumeItem{Customized TensorFlow training and evaluation for train and evaluate computer vision defect-detection models, using OpenCV-preprocessed inspection images to improve defect detection F1 by 0.12 and reduce training time from 6h to 4h.}
    \resumeItem{Collaborated with mentors to architect computer vision defect detection aligned to real manufacturing inspection workflows, engineering cross-team inspection automation and reducing integration bugs from 31 to 17 per sprint across six teams.}
  \resumeItemListEnd

\resumeSubheading
  {Machine Learning Intern}{May 2023 -- December 2023}
  {Indian Institute of Technology, Indore}{Indore, India}
  \resumeItemListStart
    \resumeItem{Calibrated PyTorch defect-detection model architectures for inspection images by implementing and iterating on model designs as an AI engineer, using OpenCV preprocessing to validate changes and reduce false positives by 3x in Q.}
    \resumeItem{Established OpenCV-based preprocessing for inspection images, integrating image data pipelines to support computer vision defect detection workflows, orchestrating 59 DAG tasks across 2 worker nodes.}
    \resumeItem{Uncovered manufacturing/quality inspection environment workflows to deliver defect detection capabilities in real-time environments, enabling quality monitoring with computer vision and reducing mean alert noise from 71 pages/week to 7.}
  \resumeItemListEnd

\resumeSubHeadingListEnd

